import json
import os

output_path = os.environ.get('OUTPUT_PATH', '')

# Check if the output file exists to confirm success
if os.path.exists(output_path):
    result = {
        "output_path": output_path,
        "status": "success"
    }
else:
    result = {
        "output_path": output_path,
        "status": "failed"
    }

print(json.dumps(result))
